   oh_nand2 #(.SIM("switch"),
	      .NMODEL("nmos"),
	      .PMODEL("pmos"),
	      .W({0,1,2,3}),
	      .L({4,5,6,7}),
	      .M({8,9,10,11}),
	      .NF({12,13,14,15}))
   dut (/*AUTOINST*/
	// Outputs
	.z			(z),
	// Inputs
	.vdd			(vdd),
	.vss			(vss),
	.a			(a),
	.b			(b));



endmodule // top
